$ErrorActionPreference='Stop'
$root=Split-Path $PSScriptRoot -Parent;$evidence=Join-Path $root 'docs/evidence'
$groups=@(
 @{name='Ledger and transport';expected=54;file='ledger-tests.txt'},
 @{name='Save conflicts, backups, preferences and OAuth';expected=55;file='vault-tests.txt'},
 @{name='Streaming, large saves and devices';expected=15;file='streaming-device-tests.txt'},
 @{name='Passcode persistence and throttling';expected=9;file='security-tests.txt'},
 @{name='WPF app protection';expected=15;file='app-lock-tests.txt'},
 @{name='Add-on peers, conflicts and rollback';expected=18;file='setup-tests.txt'},
 @{name='GameActivity history and duplicate protection';expected=18;file='activity-tests.txt'},
 @{name='HLTB absolute uploads, retries and identity checks';expected=11;file='hltb-tests.txt'},
 @{name='Pinned Rclone download and integrity';expected=4;file='runtime-tests.txt'}
)
foreach($group in $groups){$log=Get-Content (Join-Path $evidence $group.file) -Raw;if($log -notmatch ('RESULT '+$group.expected+' passed, 0 failed')){throw ('Missing passing evidence: '+$group.name)};$group.passed=$group.expected;$group.failed=0}
$runs=@();foreach($prefix in @('activity-final-local','activity-final-cloud','activity-online')){foreach($peer in @('A','B','Verify')){$file=$prefix+'-'+$peer+'.json';$value=Get-Content (Join-Path $evidence $file) -Raw|ConvertFrom-Json;if(!$value.passed){throw ('Failed host run '+$file)};$runs+=@{name=$prefix+'-'+$peer;evidence=$file;passed=$true;playtime=$value.playtime;sessions=$value.gameActivitySessions;onlineVerified=$value.onlineHltbWritesTested}}}
$live=Get-Content (Join-Path $evidence 'hltb-live.json') -Raw|ConvertFrom-Json;$restored=Get-Content (Join-Path $evidence 'hltb-live-restored.json') -Raw|ConvertFrom-Json
if(!$live.passed-or !$restored.testProgressRestored){throw 'Live HLTB check/restoration incomplete'}
$oldReport=Join-Path $root 'docs/ACCEPTANCE-0.4.md';if(!(Test-Path $oldReport)){Copy-Item (Join-Path $root 'docs/ACCEPTANCE.md') $oldReport}
$tally=@{version='0.5.0';unitPassed=199;unitFailed=0;groups=$groups;activityHosts=$runs;liveHltb=$live;liveHltbRestored=$restored;allActivityRunsPassed=$true;previousReleaseEvidence='ACCEPTANCE-0.4.md';physicalRogAllyTested=$false}
$tally|ConvertTo-Json -Depth 12|Set-Content (Join-Path $evidence 'acceptance-tally.json')
$lines=@('# Acceptance report — Playnite Link 0.5.0','','Windows 11, real Playnite 10.62 Desktop and Fullscreen applications, installed GameActivity 3.7 and HowLongToBeat 3.13. Separate profiles, libraries, game IDs, device identities and IPC pipes simulate two equal devices. A synthetic executable is launched through Playnite; no personal saves are used.','','| Automated group | Passed | Failed |','|---|---:|---:|')
foreach($group in $groups){$lines+='| '+$group.name+' | '+$group.passed+' | 0 |'}
$lines+=@('','**199 automated checks passed.**','','## Actual two-device runs','','| Run | Playnite seconds | GameActivity sessions | Online HLTB verified |','|---|---:|---:|---|')
foreach($run in $runs){$lines+='| '+$run.name+' | '+$run.playtime+' | '+$run.sessions+' | '+$run.onlineVerified+' |'}
$lines+=@('','Each peer performs five repeated syncs. Peer A is restarted and syncs five more times with zero game-start/game-stop callbacks. All runs assert exact Playnite playtime/count, native GameActivity row count/summed seconds and HowLongToBeat Playnite-model playtime/count. Existing provider games link through the actual Connect button without manual identities.','','The cloud run uses the existing personal Google OAuth/Rclone connection in a unique synthetic Drive subfolder. Both add-ons are enabled on both peers. The separate online HLTB run uses the same real account independently authorized in two isolated profiles, with real profile submissions from the normal synchronization path. Two real sessions increase the existing online entry by 16 seconds; repeated syncs and restart retain the absolute merged value. A guarded restoration returns the profile to its original progress; that restoration is verified online. Lists, reviews and completion fields are also compared before/after live no-op submissions. No online entry is duplicated or invented. Encrypted HLTB cookies are copied only to private local acceptance labs; they are not cloud-synced or packaged.','','## UI and regression checks','','The Desktop and Fullscreen save/conflict host probes pass again: two real game stops, local/cloud conflict choices, canceled launch, backups, preferences, stable navigation and retained draft state. Warm metadata checks measured 615 ms (Desktop) and 635 ms (Fullscreen) using a local Rclone alias, with no idle save scan or global progress window. These are not WAN latency claims.','','Actual GameActivity Desktop detail and Playnite Link session-history windows were rendered and visually inspected. Native GameActivity detailed/chart views require resources absent from the Fullscreen theme; Link provides a theme-aware session history using actual native data in both modes. Tests do not patch third-party styles or claim native Fullscreen chart compatibility. Screenshots and machine-readable results are in evidence/.','','## Boundaries','','- Fresh connections auto-link unambiguous provider identities. Manual games/ambiguous duplicates need a reviewed shared identity; save folders need a local selection. Settings and sign-ins stay local.','- GameActivity copied histories are deduplicated by stable identity. Ambiguous timestamps, edited/deleted tracked sessions and elapsed-time disagreements require review. A problematic game does not block other games. Aggregate-only historical counts cannot supply missing session dates.','- Online HLTB updates are opt-in and require its local sign-in plus an existing, correctly mapped profile entry. New entries are not automatically created, avoiding duplicate creation races. HLTB has no numeric session-count field equivalent to the GameActivity session list.','- HLTB updates set progress absolutely, preserve greater online progress and alter no other fields. Durable receipts and periodic fresh reads repair stale progress after retries; HLTB offers no conditional-write guarantee against simultaneous external writers.','- New Google accounts still need a personal Desktop OAuth client to avoid shared-project quota. The user-specific client/credentials are never distributed. Rclone runtime acquisition is automatic, pinned and checksum-verified.','- Physical ROG Ally controls were not tested. Two actual Windows Playnite profiles exercise Desktop and Fullscreen behavior; this does not claim a second physical machine.','','## Harness correction','','An initial cloud fixture selected the first listed remote rather than its fixture alias. It was stopped, its synthetic device registration retired, and an audit verified zero synthetic ledger objects published in the personal root and no personal save modification. The picker now explicitly selects and asserts the fixture alias before Connect. See evidence/activity-harness-retirement.json. Subsequent cloud runs use unique isolated prefixes.','','Earlier save, device, add-on and OAuth cloud acceptance remains recorded in [the 0.4 report](ACCEPTANCE-0.4.md).')
$lines|Set-Content (Join-Path $root 'docs/ACCEPTANCE.md')
Write-Output 'Verified 199 checks and nine activity host phases; wrote version 0.5 acceptance report.'


